ss="cart-actions"><form method="post" action="actions/clear_cart.php"><button class="btn btn-danger" type="submit"><i class="fa-solid fa-trash"></i> Vider le panier</button></form></div><?php if ($items): ?><form class="checkout-form" method="post" action="actions/place_order.php"><h2>Finaliser la commande</h2><div class="row g-3"><div class="col-md-6"><input class="form-control" name="customer_name" required placeholder="Nom complet"></div><div class="col-md-6"><input class="form-control" name="customer_phone" required placeholder="Téléphone"></div></div><button class="btn btn-gold mt-3" type="submit"><i class="fa-solid fa-lock"></i> Procéder au paiement</button></form><?php endif; ?></div></section></main><?php include __DIR__ . '/includes/footer.php'; ?>
